function showPopup() {
	// Exit the function if the banner has been closed
  if (sessionStorage.getItem('bannerClosed')) return;
  
  const fadeOutElement = document.querySelector('.fade-out');
  const modal = document.querySelector('.ExitIntentModal');

  if (fadeOutElement) {
    fadeOutElement.classList.remove('fade-out');
  }
  
  if (modal) {
    modal.classList.add("fade-in", "is-open");
  }
  
  if(!widget.phonenumber) {
    const element = document.getElementById('secondaryBody');
    element.style.display = 'none';
  }
}

function closePopup() {
  document.body.classList.remove("is-open");
  const modal = document.querySelector('.ExitIntentModal');
  if (modal) {
    modal.remove();
  }
  // Setting sessionStorage to prevent banner from showing again with in that session
  sessionStorage.setItem('bannerClosed', 'true');
}

