// Flags to prevent multiple triggers
let hasFiredModalShownEvent = false;
let modalTriggered = false;
let eventListenersBound = false; // Prevent duplicate event listeners

// Constants for exit intent detection
const EXIT_ZONE_WIDTH = 150; // pixels from right edge
const EXIT_ZONE_HEIGHT = 100; // pixels from top edge  
const SCROLL_PERCENTAGE_MULTIPLIER = 100; // percentage multiplier



// Wait for the body element to be ready
utils.waitForElement("body").then(function (element) {
  // Only proceed if the user hasn't closed the banner in this session
  if (!sessionStorage.getItem("bannerClosed")) {
    // 1. Inject the modal HTML
    element.insertAdjacentHTML("afterbegin", widget.$html);
    
    // 2. Improved exit-intent trigger - detects upward movement with exit intent
    let lastMouseY = -1;
    let mouseMovingUp = false;
    
    // Track mouse movement to detect upward movement (towards browser chrome)
    document.addEventListener("mousemove", function(e) {
      // Only check if modal hasn't been triggered yet
      if (modalTriggered || sessionStorage.getItem("bannerClosed")) {
        return;
      }
      
      const currentMouseY = e.clientY;
      
      // Detect if mouse is moving upward
      if (lastMouseY !== -1 && currentMouseY < lastMouseY) {
        mouseMovingUp = true;
      } else {
        mouseMovingUp = false;
      }
      
      lastMouseY = currentMouseY;
    });
    
    // Trigger on mouseleave if mouse was moving upward (towards browser controls)
    element.addEventListener("mouseleave", function(e) {
      if (!modalTriggered && !sessionStorage.getItem("bannerClosed")) {
        const mouseY = e.clientY;
        const mouseX = e.clientX;
        
        if (isGenuineExitIntent(mouseX, mouseY, mouseMovingUp)) {
          showPopup("exit_intent");
        }
      }
    });

    // 3. Scroll-depth trigger using waitUntil (only if threshold is meaningful)
    if (widget.scrollDepthThreshold && widget.scrollDepthThreshold > 0) {
      utils.waitUntil(function() {
        // Don't continue checking if the banner has been closed or modal already triggered
        if (sessionStorage.getItem("bannerClosed") || modalTriggered) {
          return false;
        }
        
        // Calculate scroll percentage
        const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
        const docHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
        
        // Handle edge case where page is too short to scroll
        if (docHeight <= 0) {
          return false;
        }
        
        const scrollPercent = (scrollTop / docHeight) * SCROLL_PERCENTAGE_MULTIPLIER;
        
        // Return true when the threshold is met
        return scrollPercent >= widget.scrollDepthThreshold;
      }).then(function() {
        // This code runs only ONCE when scroll depth is reached
        if (!modalTriggered && !sessionStorage.getItem("bannerClosed")) {
          showPopup("scroll_depth");
        }
      });
    }
  }
});

// --- Helper Functions ---

// Helper function to determine if this is genuine exit intent
function isGenuineExitIntent(mouseX, mouseY, mouseMovingUp) {
  const leavingTowardsTop = mouseY <= 0;
  const leavingTowardsTopRight = (
    mouseMovingUp && 
    mouseY <= EXIT_ZONE_HEIGHT && 
    mouseX >= (window.innerWidth - EXIT_ZONE_WIDTH)
  );
  return leavingTowardsTop || leavingTowardsTopRight;
}

function showPopup(triggerType) {
  // Exit if the banner has been closed or modal already triggered
  if (sessionStorage.getItem("bannerClosed") || modalTriggered) {
    return;
  }

  // Set flag to prevent multiple triggers
  modalTriggered = true;

  displayModal();
  setupModalProtection();
  trackModalShown(triggerType);
  configureModalElements();
  
  // IMPROVEMENT: Bind event listeners only once when modal first shows
  if (!eventListenersBound) {
    bindEventListeners();
    eventListenersBound = true;
  }
}

function displayModal() {
  const fadeOutElement = document.querySelector(".fade-out");
  const modal = document.querySelector(".ExitIntentModal");

  if (fadeOutElement) {
    fadeOutElement.classList.remove("fade-out");
  }

  if (modal) {
    modal.classList.add("fade-in", "is-open");
  }
}

function setupModalProtection() {
  const modal = document.querySelector(".ExitIntentModal");
  
  // OneTrust Protection: Monitor modal for unexpected class changes and restore is-open class
  if (!modal) return;

  const modalObserver = new MutationObserver(function(mutations) {
    // eslint-disable-next-line complexity
    mutations.forEach(function(mutation) {
      // Only process class changes where 'is-open' was removed
      if (mutation.type === 'attributes' && 
          mutation.attributeName === 'class' &&
          mutation.oldValue && 
          mutation.oldValue.includes('is-open') &&
          !modal.className.includes('is-open')) {
        modal.classList.add('is-open');
      }
    });
  });
  
  modalObserver.observe(modal, { attributes: true, attributeOldValue: true });
}

function trackModalShown(triggerType) {
  // Track the modal shown event (only once)
  if (!hasFiredModalShownEvent) {
    window.optimizely = window.optimizely || [];
    window.optimizely.push({
      type: "event",
      eventName: "modal_shown",
      properties: {
        trigger_type: triggerType || "unknown"
      }
    });
    hasFiredModalShownEvent = true;
  }
}

function configureModalElements() {
  // Hide elements based on widget configuration
  if (!widget.phonenumber) hideElementById("secondaryBody");
  if (!widget.buttoncopy) hideElementById("optlyCtaButton");
}

function closePopup() {
  document.body.classList.remove("is-open");
  const modal = document.querySelector(".ExitIntentModal");
  if (modal) {
    modal.remove();
  }
  
  // Setting sessionStorage to prevent banner from showing again within that session
  sessionStorage.setItem("bannerClosed", "true");
  
  // Track close event
  window.optimizely = window.optimizely || [];
  window.optimizely.push({
    type: "event",
    eventName: "modal_closed"
  });

  // IMPROVEMENT: Reset event listeners flag since modal is removed
  eventListenersBound = false;
  
  // FIXED: Remove the outside click event listener with the same options used when adding
  document.body.removeEventListener("click", handleOutsideClick, { capture: true });
}

function bindEventListeners() {
  // Targets the <a> inside the div
  const ctaButton = document.querySelector("#optlyCtaButton a");

  if (ctaButton) {
    // Get URL parameters
    const urlParams = new URLSearchParams(window.location.search);
    const crosskey = urlParams.get("crosskey");
    
    // Construct a new URL object, ensuring that even relative URLs are handled correctly
    const buttonUrl = new URL(ctaButton.href, window.location.origin);

    // Add parameters to button URL if they exist
    if (crosskey) {
      buttonUrl.searchParams.set("campaignCode", crosskey);
    }
    
    ctaButton.href = buttonUrl.toString();
  }

  // Modal close button - x
  const closeBtn = document.querySelector(".exit-popup-close");
  if (closeBtn) {
    closeBtn.addEventListener("click", closePopup);
  }

  // CTA button
  const cta = document.querySelector(".CTA");
  if (cta) {
    cta.addEventListener("click", function() {
      // Track CTA click
      window.optimizely = window.optimizely || [];
      window.optimizely.push({
        type: "event",
        eventName: "modal_cta_clicked"
      });
      closePopup();
    });
  }

  // FIXED: Click outside modal to close - use capture phase to catch events early
  document.body.addEventListener("click", handleOutsideClick, { capture: true });
}

// IMPROVEMENT: Separate function for outside click handling for better management
function handleOutsideClick(e) {
  // Optimized OneTrust protection - simplified to most effective selectors
  if (
    e.target.closest(".ExitIntentModal-Body") ||            // Inside modal
    e.target.closest("[id^='onetrust']") ||                 // Any OneTrust element by ID (catches onetrust-banner-sdk, onetrust-pc-sdk, etc.)
    e.target.closest("[class*='onetrust']")                 // Any OneTrust element by class (catches all onetrust-* classes)
  ) {
    return; // Don't close modal - allow OneTrust to handle its own events
  }
  
  // Close modal only if clicked outside both modal and OneTrust elements
  closePopup(); // This will handle the event listener cleanup
}

// Helper function to hide elements
const hideElementById = (id) => {
  const element = document.getElementById(id);
  if (element) {
    element.style.display = "none";
  }
};
